using System.IO;
using System.Numerics;
using System.Text.Json;
using System.Security.Cryptography;
using HKX2E;
namespace DanceStudio;
public static class SyncMappingTests {
 public static void Run(string input,string output){Directory.CreateDirectory(output);var original=SongProject.Load(input);var rig=Rig.Load(original.Skeleton);int checks=0;var results=new List<object>();var nativeCases=new List<object>();void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}
  string source=Path.Combine(output,"time-coded.hkx");var f=MotionClip.Read(original.Dance.Path);short[] map=[0,4,6,97];var transforms=new List<Matrix4x4>();for(int i=0;i<=3600;i++){float t=i/24f;foreach(int b in map)transforms.Add(new Pose(new Vector3(t*(b==97?2:.25f),b==97?20:0,b==97?100:t*.01f),PoseEdits.Yaw(t*.1),new Vector3(1+t*.0001f)).Matrix());}var a=new hkaInterleavedUncompressedAnimation{type=1,duration=150,numberOfTransformTracks=4,numberOfFloatTracks=0,transforms=transforms,floats=[],annotationTracks=[]};f.Container.animations=[a];f.Container.bindings=[new hkaAnimationBinding{animation=a,originalSkeletonName=rig.Name,transformTrackToBoneIndices=map.ToList(),floatTrackToFloatSlotIndices=[]}];f.Container.skeletons=[];using(var file=File.Create(source))new PackFileSerializer().Serialize(f.Root,new BinaryWriterEx(file),f.Header);var motion=MotionClip.Load(source);motion.ValidateRig(rig);
  // Audio is deterministic, quiet PCM; exports use actual WAV baking and runtime parsing.
  var audio=new WaveAudio{SampleRate=8000,Channels=1,Pcm=new byte[150*8000*2]};audio.Path=Path.Combine(output,"source.wav");audio.Bake(audio.Path,new TrackEdit{Out=150},0,150);audio=WaveAudio.Load(audio.Path);
  Pose CameraAt(SongProject p,double local)=>PoseEdits.StageCamera(motion.World(rig,Math.Clamp(p.Camera.SourceTime(p.ExportIn+local),p.Camera.In,p.Camera.Out))[97],p.CameraYaw,p.CameraForward,p.MirrorCamera,p.PlayerYaw);
  (double,double,double) Errors(MotionClip src,MotionClip baked,TrackEdit edit,double begin,double[] times){double pos=0,rot=0,scale=0;foreach(double t in times){double st=Math.Clamp(edit.SourceTime(begin+t),edit.In,edit.Out);var x=src.At(st);var y=baked.At(t);var wx=src.World(rig,st);var wy=baked.World(rig,t);for(int i=0;i<src.Tracks;i++){pos=Math.Max(pos,Vector3.Distance(x[i].T,y[i].T));rot=Math.Max(rot,MotionComparison.Angle(x[i].R,y[i].R));scale=Math.Max(scale,Vector3.Distance(x[i].S,y[i].S));pos=Math.Max(pos,Vector3.Distance(wx[src.BoneMap[i]].T,wy[src.BoneMap[i]].T));}Check(pos<.002&&rot<.003&&scale<.000003,"TRS/COM mapping at actual seconds");}return(pos,rot,scale);}
  var cases=new[]{("A1",new TrackEdit{In=5,Out=15},0.0,10.0,new[]{0.0,5,10}), ("A2",new TrackEdit{In=10,Out=18,Speed=2},0.0,4.0,new[]{0.0,1,2,3,4}), ("A3",new TrackEdit{In=10,Out=14,Speed=.5},0.0,8.0,new[]{0.0,2,4,8}), ("A4",new TrackEdit{In=5,Out=15,Start=3},0.0,13.0,new[]{0.0,1,3,8,13}), ("A5",new TrackEdit{In=5,Out=25,Start=2,Speed=2},4.0,10.0,new[]{0.0,1,3,6}), ("A6",new TrackEdit{In=5,Out=8},0.0,8.0,new[]{0.0,1,3,5,8})};
  foreach(var(name,edit,begin,end,times)in cases){double[] wanted=name switch{"A1"=>[5,10,15],"A2"=>[10,12,14,16,18],"A3"=>[10,11,12,14],"A4"=>[5,5,5,10,15],"A5"=>[9,11,15,21],_=>[5,6,8,8,8]};for(int i=0;i<times.Length;i++)Check(Math.Abs(Math.Clamp(edit.SourceTime(begin+times[i]),edit.In,edit.Out)-wanted[i])<1e-10,"explicit source seconds "+name);string path=Path.Combine(output,name+".hkx");motion.Bake(path,edit,begin,end,24,null,rig);var baked=MotionClip.Load(path);Check(Math.Abs(baked.Duration-(end-begin))<.00001,"HKX duration");var error=Errors(motion,baked,edit,begin,times);
   edit.Path=source;var cp=new SongProject{Skeleton=rig.SourceReference??Rig.BuiltinId,Dance=edit,Camera=edit,Audio=new(){Path=audio.Path,Out=150},ExportIn=begin,ExportOut=end,CameraBone=97,CameraSampleFps=new(){Mode="Manual",Value=30}};string cf=Exporter.Export(output,cp,motion,motion,audio,rig);var cameraExpected=times.Select((t,i)=>{var pose=PoseEdits.StageCamera(motion.World(rig,wanted[i])[97],0,"+Y",false,0);return new{time=t,position=new[]{pose.T.X,pose.T.Y,pose.T.Z},rotation=new[]{pose.R.X,pose.R.Y,pose.R.Z,pose.R.W}};}).ToArray();File.WriteAllText(Path.Combine(cf,"expected-sync.json"),JsonSerializer.Serialize(cameraExpected,SongProject.Json));nativeCases.Add(new{folder=cf,duration=end-begin});results.Add(new{name,sourceTimes=times.Select(t=>Math.Clamp(edit.SourceTime(begin+t),edit.In,edit.Out)),error=new{position=error.Item1,angle=error.Item2,scale=error.Item3},frames=baked.Frames});}
  // Repeat boundary/interior mapping against real Booo using its existing decoder as reference.
  var real=MotionClip.Load(original.Dance.Path,original.Dance.HkxBindingIndex,original.Dance.IdentityRigProof);foreach(var(name,edit,begin,end,times)in cases){string path=Path.Combine(output,"real-"+name+".hkx");real.Bake(path,edit,begin,end,24,null,rig);var error=Errors(real,MotionClip.Load(path),edit,begin,times);results.Add(new{name="Booo-"+name,error=new{position=error.Item1,angle=error.Item2,scale=error.Item3}});}
  var packages=new List<object>();var assetHashes=new Dictionary<string,string>();string Hash(string path)=>Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)));
  foreach(var(df,cf)in new[]{(24,30),(30,24),(24,60),(60,30),(24,24),(60,60)}){
   var p=new SongProject{Title=$"Sync {df}-{cf}",Skeleton=rig.SourceReference??Rig.BuiltinId,Dance=new TrackEdit{Path=source,In=5,Out=145,Start=2,Speed=1},Camera=new TrackEdit{Path=source,In=10,Out=150,Start=3,Speed=1},Audio=new TrackEdit{Path=audio.Path,Out=150},ExportIn=4,ExportOut=129.03,CameraBone=97,DanceOutputFps=new(){Mode="Manual",Value=df},CameraSampleFps=new(){Mode="Manual",Value=cf}};
   string folder=Exporter.Export(output,p,motion,motion,audio,rig);string dancePath=Path.Combine(folder,"tracks/dance.hkx"),cameraPath=Path.Combine(folder,"tracks/camera.samples.json"),wavePath=Path.Combine(folder,"tracks/music.wav");var baked=MotionClip.Load(dancePath);double duration=p.ExportOut-p.ExportIn;double[] times=[0,.5,1,10,30,60,120,duration-1e-4,duration];var err=Errors(motion,baked,p.Dance,p.ExportIn,times);var expected=times.Select(t=>{var pose=CameraAt(p,t);return new{time=t,position=new[]{pose.T.X,pose.T.Y,pose.T.Z},rotation=new[]{pose.R.X,pose.R.Y,pose.R.Z,pose.R.W}};}).ToArray();File.WriteAllText(Path.Combine(folder,"expected-sync.json"),JsonSerializer.Serialize(expected,SongProject.Json));
   using var doc=JsonDocument.Parse(File.ReadAllText(cameraPath));var rows=doc.RootElement.GetProperty("samples").EnumerateArray().ToArray();Check(rows[0].GetProperty("time").GetDouble()==0&&Math.Abs(rows[^1].GetProperty("time").GetDouble()-duration)<1e-12,"camera exact endpoints");Check(rows.Zip(rows.Skip(1),(x,y)=>y.GetProperty("time").GetDouble()>x.GetProperty("time").GetDouble()).All(x=>x),"strict camera timestamps");Check(rows.Take(rows.Length-1).Select((row,i)=>Math.Abs(row.GetProperty("time").GetDouble()-i/(double)cf)<1e-10).All(x=>x),"fixed camera sampling period");Check(rows[^1].GetProperty("time").GetDouble()-rows[^2].GetProperty("time").GetDouble()<=1.0/cf+1e-10,"short terminal interval only");Check(baked.Frames==Math.Max(2,(int)Math.Round(duration*df)+1),"HKX uniform frame count");Check(Math.Abs(WaveAudio.Load(wavePath).Duration-duration)<=1.0/8000,"audio output length quantum");
   string dh=Hash(dancePath),ch=Hash(cameraPath),wh=Hash(wavePath);void Same(string key,string hash){if(assetHashes.TryGetValue(key,out var prior))Check(prior==hash,"independent asset SHA "+key);else assetHashes[key]=hash;}Same("dance-"+df,dh);Same("camera-"+cf,ch);Same("audio",wh);
   nativeCases.Add(new{folder,duration});packages.Add(new{danceFps=df,cameraFps=cf,folder,duration,danceDuration=baked.Duration,danceHash=dh,cameraHash=ch,audioHash=wh,cameraSamples=rows.Length,error=new{position=err.Item1,angle=err.Item2,scale=err.Item3}});
  }
  // Different Start values and hold behavior checked through actual camera JSON as well.
  var offset=new SongProject{Skeleton=rig.SourceReference??Rig.BuiltinId,Dance=new(){Path=source,In=5,Out=8,Start=2},Camera=new(){Path=source,In=10,Out=12,Start=4},Audio=new(){Path=audio.Path,Out=150},ExportOut=9,CameraBone=97,CameraSampleFps=new(){Mode="Manual",Value=30}};string of=Exporter.Export(output,offset,motion,motion,audio,rig);using(var od=JsonDocument.Parse(File.ReadAllText(Path.Combine(of,"tracks/camera.samples.json")))){foreach(double t in new[]{0.0,2,4,6,9}){var row=od.RootElement.GetProperty("samples").EnumerateArray().MinBy(x=>Math.Abs(x.GetProperty("time").GetDouble()-t));var v=row.GetProperty("position");var expected=CameraAt(offset,t);Check(Vector3.Distance(new(v[0].GetSingle(),v[1].GetSingle(),v[2].GetSingle()),expected.T)<.0001,"prestart/hold camera");}}
  // Known ceil floating boundary bug, plus non-integral terminal interval.
  var boundary=offset;boundary.ExportOut=31.0/30;boundary.CameraSampleFps.Value=30;string bf=Exporter.Export(output,boundary,motion,motion,audio,rig);using(var bd=JsonDocument.Parse(File.ReadAllText(Path.Combine(bf,"tracks/camera.samples.json")))){var stamps=bd.RootElement.GetProperty("samples").EnumerateArray().Select(x=>x.GetProperty("time").GetDouble()).ToArray();Check(stamps.Length==32&&stamps.Zip(stamps.Skip(1),(x,y)=>y>x).All(x=>x),"31/30 terminal timestamp regression");}
  File.WriteAllText(Path.Combine(output,"boundary-path.txt"),bf);File.WriteAllText(Path.Combine(output,"native-cases.json"),JsonSerializer.Serialize(nativeCases,SongProject.Json));
  File.WriteAllText(Path.Combine(output,"packages.json"),JsonSerializer.Serialize(packages,SongProject.Json));File.WriteAllText(Path.Combine(output,"mapping-results.json"),JsonSerializer.Serialize(results,SongProject.Json));File.WriteAllText(Path.Combine(output,"validation.json"),JsonSerializer.Serialize(new{passed=true,checks,mappingCases=12,fpsCombinations=6,gameTested=false,decoderReference="Matcher decoded frames + managed interpolation; not independent Havok",positionTolerance=.002,angleToleranceDegrees=.003,scaleTolerance=.000003},SongProject.Json));
 }
}
